{
  "ruleset_id": "programma-dopolnitelnogo-obrazovaniya",
  "rules": [
    {
      "description": "Организация должна иметь действующую лицензию на образовательную деятельность.",
      "severity": "critical",
      "category": "лицензия",
      "condition": {
        "field": "documents.education_license.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Объём программы должен составлять не менее 72 часов.",
      "severity": "critical",
      "category": "объём",
      "condition": {
        "field": "curriculum.total_hours",
        "op": "ge",
        "value": 72
      }
    },
    {
      "description": "Не менее 80% преподавателей должны иметь профильную квалификацию.",
      "severity": "critical",
      "category": "квалификация",
      "condition": {
        "field": "staff.qualified_teachers_pct",
        "op": "ge",
        "value": 80
      }
    },
    {
      "description": "Формат реализации программы допускается только очный или смешанный.",
      "severity": "critical",
      "category": "формат",
      "condition": {
        "field": "programme.delivery_format",
        "op": "in",
        "value": [
          "очно",
          "смешанно"
        ]
      }
    }
  ]
}

{
  "ruleset_id": "subsidy-energy-efficiency",
  "rules": [
    {
      "description": "Проект должен снизить потребление энергии не менее чем на 20%.",
      "severity": "critical",
      "category": "энергоэффективность",
      "condition": {
        "field": "project.energy_consumption_reduction_pct",
        "op": "ge",
        "value": 20
      }
    },
    {
      "description": "Доля софинансирования заявителя должна составлять не менее 30%.",
      "severity": "critical",
      "category": "софинансирование",
      "condition": {
        "field": "budget.co_financing_pct",
        "op": "ge",
        "value": 30
      }
    },
    {
      "description": "К заявке должен быть приложен технический паспорт объекта.",
      "severity": "critical",
      "category": "документы",
      "condition": {
        "field": "documents.technical_passport.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Работы должны быть завершены не позднее 31 декабря 2027 года.",
      "severity": "critical",
      "category": "срок завершения",
      "condition": {
        "field": "project.completion_date",
        "op": "before",
        "value": "2027-12-31"
      }
    }
  ]
}

{
  "ruleset_id": "nordstar-main-track-v2-4",
  "rules": [
    {
      "description": "Заявитель основного трека должен быть зарегистрирован не менее 24 месяцев.",
      "severity": "critical",
      "category": "допуск",
      "condition": {
        "field": "org_v2.months_registered",
        "op": "lt",
        "value": 24
      }
    },
    {
      "description": "Запрашиваемая сумма гранта основного трека не должна превышать 250000 евро.",
      "severity": "critical",
      "category": "лимит",
      "condition": {
        "field": "org_v2.total_requested",
        "op": "gt",
        "value": 250000
      }
    },
    {
      "description": "К заявке должно быть приложено аудиторское заключение.",
      "severity": "critical",
      "category": "аудит",
      "condition": {
        "field": "documents.audit_report.present",
        "op": "eq",
        "value": false
      }
    },
    {
      "description": "Заявка на цикл 2027 года не принимается после 31 марта 2027 года.",
      "severity": "critical",
      "category": "срок",
      "condition": {
        "field": "org_v2.submission_date",
        "op": "after",
        "value": "2027-03-31"
      }
    },
    {
      "description": "Численность сотрудников в заявке должна совпадать с численностью в годовом отчёте.",
      "severity": "major",
      "category": "согласованность",
      "condition": {
        "op": "consistent",
        "fields": [
          "org_v2.declared_headcount",
          "annual_report.headcount"
        ]
      }
    },
    {
      "description": "Годовой отчёт должен быть подготовлен по МСФО.",
      "severity": "minor",
      "category": "отчётность",
      "condition": {
        "field": "annual_report.ifrs",
        "op": "eq",
        "value": false
      }
    }
  ]
}

{
  "ruleset_id": "fond-primer-grant-program-2026",
  "rules": [
    {
      "description": "Организация, зарегистрированная менее 12 месяцев на дату подачи, автоматически отклоняется.",
      "severity": "critical",
      "category": "допуск",
      "condition": {
        "field": "application_form.months_registered",
        "op": "lt",
        "value": 12
      }
    },
    {
      "description": "Заявка с запрашиваемой суммой свыше 100000 евро возвращается на доработку.",
      "severity": "major",
      "category": "лимит бюджета",
      "condition": {
        "field": "application_form.requested_total_eur",
        "op": "gt",
        "value": 100000
      }
    },
    {
      "description": "Расходы на оборудование не должны превышать 40 процентов общего бюджета.",
      "severity": "major",
      "category": "оборудование",
      "condition": {
        "field": "budget.row.equipment.share_pct",
        "op": "gt",
        "value": 40
      }
    },
    {
      "description": "Заявка без формы заявки не принимается и отклоняется.",
      "severity": "critical",
      "category": "обязательные документы",
      "condition": {
        "field": "documents.application_form.present",
        "op": "eq",
        "value": false
      }
    },
    {
      "description": "Заявка без детализированного бюджета не принимается и отклоняется.",
      "severity": "critical",
      "category": "обязательные документы",
      "condition": {
        "field": "documents.budget.present",
        "op": "eq",
        "value": false
      }
    },
    {
      "description": "Заявка без свидетельства о регистрации или выписки из реестра не принимается и отклоняется.",
      "severity": "critical",
      "category": "обязательные документы",
      "condition": {
        "field": "documents.registration_cert.present",
        "op": "eq",
        "value": false
      }
    },
    {
      "description": "Заявка без последней финансовой отчетности не принимается и отклоняется.",
      "severity": "critical",
      "category": "обязательные документы",
      "condition": {
        "field": "documents.finance_statement.present",
        "op": "eq",
        "value": false
      }
    },
    {
      "description": "Заявки, поданные после 1 октября 2026 года, возвращаются.",
      "severity": "major",
      "category": "срок подачи",
      "condition": {
        "field": "application_form.submission_date",
        "op": "after",
        "value": "2026-10-01"
      }
    },
    {
      "description": "Неподписанная форма заявки отклоняется.",
      "severity": "critical",
      "category": "подпись",
      "condition": {
        "field": "application_form.signature_present",
        "op": "eq",
        "value": false
      }
    },
    {
      "description": "Запрашиваемая в форме сумма должна точно совпадать с итогом детализированного бюджета.",
      "severity": "major",
      "category": "согласованность",
      "condition": {
        "op": "consistent",
        "fields": [
          "application_form.requested_total_eur",
          "budget.totals.total"
        ]
      }
    },
    {
      "description": "Финансовая отчетность должна охватывать FY2025.",
      "severity": "minor",
      "category": "отчетный период",
      "condition": {
        "field": "finance_statement.period",
        "op": "ne",
        "value": "FY2025"
      }
    }
  ]
}

{
  "ruleset_id": "programma-kapitalnogo-remonta",
  "rules": [
    {
      "description": "Дом должен быть построен не позднее 2005 года.",
      "severity": "critical",
      "category": "год_строительства",
      "condition": {
        "field": "building.construction_year",
        "op": "le",
        "value": 2005
      }
    },
    {
      "description": "Решение собственников должны поддержать не менее 66% голосов.",
      "severity": "critical",
      "category": "одобрение_собственников",
      "condition": {
        "field": "owners.approval_pct",
        "op": "ge",
        "value": 66
      }
    },
    {
      "description": "К заявке должен прилагаться акт обследования дефектов.",
      "severity": "critical",
      "category": "документы",
      "condition": {
        "field": "documents.defect_report.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Заявка должна быть подана не позднее 1 апреля 2027 года включительно.",
      "severity": "critical",
      "category": "срок_подачи",
      "condition": {
        "field": "application.submission_date",
        "op": "le",
        "value": "2027-04-01"
      }
    }
  ]
}

{
  "ruleset_id": "zakupka-medicinskih-izdeliy",
  "rules": [
    {
      "description": "Для товара обязательно наличие регистрационного удостоверения.",
      "severity": "critical",
      "category": "регистрация",
      "condition": {
        "field": "documents.medical_registration.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "На дату поставки остаточный срок годности товара должен составлять не менее 12 месяцев.",
      "severity": "critical",
      "category": "срок годности",
      "condition": {
        "field": "product.expiry_months",
        "op": "ge",
        "value": 12
      }
    },
    {
      "description": "Для изделий, требующих холодовой цепи, обязательно наличие протокола соблюдения холодовой цепи.",
      "severity": "critical",
      "category": "холодовая цепь",
      "condition": {
        "field": "documents.cold_chain_protocol.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Страной происхождения товара может быть Россия или государство ЕАЭС.",
      "severity": "critical",
      "category": "происхождение",
      "condition": {
        "field": "product.origin_country",
        "op": "in",
        "value": [
          "Россия",
          "государство ЕАЭС"
        ]
      }
    }
  ]
}

{
  "ruleset_id": "municipal_subsidy_2026",
  "rules": [
    {
      "description": "Получатель должен быть зарегистрирован не менее 12 месяцев.",
      "severity": "critical",
      "category": "регистрация",
      "condition": {
        "field": "applicant.registration_months",
        "op": "ge",
        "value": 12
      }
    },
    {
      "description": "Запрашиваемая субсидия не должна превышать 5 000 000 рублей.",
      "severity": "critical",
      "category": "сумма",
      "condition": {
        "field": "application.requested_rub",
        "op": "le",
        "value": 5000000
      }
    },
    {
      "description": "К заявке должна быть приложена финансовая отчётность за последний год.",
      "severity": "critical",
      "category": "документы",
      "condition": {
        "field": "documents.financial_statement.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Заявка должна быть подана не позднее 15 сентября 2026 года включительно.",
      "severity": "critical",
      "category": "срок подачи",
      "condition": {
        "field": "application.submission_date",
        "op": "le",
        "value": "2026-09-15"
      }
    },
    {
      "description": "Организации с задолженностью по налогам не допускаются.",
      "severity": "critical",
      "category": "налоговая задолженность",
      "condition": {
        "field": "applicant.tax_arrears",
        "op": "eq",
        "value": 0
      }
    }
  ]
}

{
  "ruleset_id": "zakupka-remontnyh-rabot",
  "rules": [
    {
      "description": "Годовая выручка поставщика должна составлять не менее 10 000 000 рублей.",
      "severity": "critical",
      "category": "финансовый порог",
      "condition": {
        "field": "supplier.annual_turnover_rub",
        "op": "ge",
        "value": 10000000
      }
    },
    {
      "description": "Для допуска требуется действующее свидетельство СРО.",
      "severity": "critical",
      "category": "допуск",
      "condition": {
        "field": "documents.sro_certificate.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Участник допускается только со статусом санкционной проверки «clear».",
      "severity": "critical",
      "category": "санкционная проверка",
      "condition": {
        "field": "supplier.sanctions_status",
        "op": "eq",
        "value": "clear"
      }
    },
    {
      "description": "Заявки принимаются не позднее 20 ноября 2026 года.",
      "severity": "critical",
      "category": "срок подачи",
      "condition": {
        "field": "bid.submission_date",
        "op": "le",
        "value": "2026-11-20"
      }
    }
  ]
}

{
  "ruleset_id": "konkurs-prikladnyh-issledovaniy",
  "rules": [
    {
      "description": "Руководитель должен иметь степень «кандидат наук» или «доктор наук».",
      "severity": "critical",
      "category": "квалификация",
      "condition": {
        "field": "researcher.degree",
        "op": "in",
        "value": [
          "кандидат наук",
          "доктор наук"
        ]
      }
    },
    {
      "description": "Руководитель должен иметь не менее трёх публикаций в рецензируемых журналах.",
      "severity": "critical",
      "category": "публикации",
      "condition": {
        "field": "researcher.peer_reviewed_publications",
        "op": "ge",
        "value": 3
      }
    },
    {
      "description": "Должно быть представлено согласие на размещение обезличенных данных исследования.",
      "severity": "critical",
      "category": "согласие",
      "condition": {
        "field": "documents.open_data_consent.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Заявленный в форме бюджет должен совпадать с итогом сметы.",
      "severity": "major",
      "category": "бюджет",
      "condition": {
        "op": "consistent",
        "fields": [
          "application.declared_budget_rub",
          "budget.total_rub"
        ]
      }
    }
  ]
}

{
  "ruleset_id": "social-contract",
  "rules": [
    {
      "description": "Домохозяйство должно находиться в Москве или Московской области.",
      "severity": "critical",
      "category": "region",
      "condition": {
        "field": "household.region",
        "op": "in",
        "value": [
          "Москва",
          "Московская область"
        ]
      }
    },
    {
      "description": "Доход на человека не должен превышать 25 000 рублей в месяц.",
      "severity": "critical",
      "category": "income",
      "condition": {
        "field": "household.monthly_income_per_person_rub",
        "op": "le",
        "value": 25000
      }
    },
    {
      "description": "Должно быть предоставлено согласие на обработку персональных данных.",
      "severity": "critical",
      "category": "consent",
      "condition": {
        "field": "documents.personal_data_consent.present",
        "op": "eq",
        "value": true
      }
    },
    {
      "description": "Заявитель должен иметь статус unemployed или job_seeker.",
      "severity": "critical",
      "category": "employment",
      "condition": {
        "field": "applicant.employment_status",
        "op": "in",
        "value": [
          "unemployed",
          "job_seeker"
        ]
      }
    }
  ]
}
